from pathlib import Path
import json,hashlib,datetime
H=Path(__file__).resolve().parent
blocks={
 'Северо-Западный район': [('Архангельская область','архангельская'),('Вологодская область','вологодская'),('Ленинградская область','ленинградская'),('Мурманская область','мурманская'),('Новгородская область','новгородская'),('Псковская область','псковская'),('Карельская АССР','карелия'),('Коми АССР','коми')],
 'Центральный район':[('Брянская область','брянская'),('Владимирская область','владимирская'),('Ивановская область','ивановская'),('Калининская область','тверская'),('Калужская область','калужская'),('Костромская область','костромская'),('Московская область','московская'),('Орловская область','орловская'),('Рязанская область','рязанская'),('Смоленская область','смоленская'),('Тульская область','тульская'),('Ярославская область','ярославская')],
 'Волго-Вятский район':[('Горьковская область','нижегородская'),('Кировская область','кировская'),('Марийская АССР','марий эл'),('Мордовская АССР','мордовия'),('Чувашская АССР','чувашская')],
 'Дополнительно прямо перечислены в определении зоны':[('Пермская область','пермский'),('Свердловская область','свердловская'),('Калининградская область','калининградская'),('Удмуртская АССР','удмуртская')]}
rows=[]
for block,units in blocks.items():
 for old,key in units:
  rows.append(dict(source_unit=old,source_block=block,source_pdf_page_1based=17 if 'Дополнительно' not in block else 15,source_printed_page=211 if 'Дополнительно' not in block else 209,axis_region_key=key,mapping_kind='historical_regional_successor_context_only',unchanged_boundary_proven=False,own_soil_or_parcel_membership=False))
assert len(rows)==29
(H/'finite_source29_to_axis_regions.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
p=dict(created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),status='BEFORE_CONTEXT_FLAG_COMPUTATION',primary_source='ЦСУ при Совете Министров РСФСР. Народное хозяйство РСФСР в 1974 году. М.: Статистика, 1975. С.209,211.',historical_reference_year=1974,publication_year=1975,source_definition='Complete 29 oblast/ASSR list: all three historical economic regions plus four explicitly named units.',map_sha256=hashlib.sha256((H/'finite_source29_to_axis_regions.json').read_bytes()).hexdigest(),value_semantics='Presence-only inherited historical Nonchernozem regional policy/statistical context. No 2021 geographic boundary containment, soil, parcel, causal mechanism or sufficient Word type7 claim.',positive_axis_region_keys=[x['axis_region_key'] for x in rows],additional_NAO_conditional=dict(axis_region_key='ненецкий',parent='Архангельская область',primary_source='same CSU yearbook population chapter PDFpage2 printed6',rule='Only after independent guardian hierarchy acceptance'),unknown_policy='All regions outside finite positive list remain NA: source-only positive context, not a contemporary exhaustive exclusion map. Federal cities and Crimea explicitly NA. Historical-only axis rows without native2021 observation retain NA even when region key matches.',assignment='Exact existing axis region key AND own native2021 census source record. No name/latitude/climate/nearest-polygon inference.',future_model_adoption='Separate candidate sidecar only; main model and typology frozen artifacts unchanged; guardian admission required before any canonical incorporation.')
(H/'preregistration.json').write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n');print(p['map_sha256'])
